import csv
import io
import random
import unittest
from src.catalogue import Catalog
from src.export_csv import to_csv


def doc(id_, title, edition="one", updated=1):
    return {"id": id_, "title": title, "edition": edition, "updated": updated}


def oracle(records, query, edition=None, limit=20):
    terms = set(query.casefold().split())
    if not terms or limit <= 0:
        return []
    matches = [d for d in records.values() if terms <= set(d["title"].casefold().split()) and (edition is None or edition == d["edition"])]
    return [d["id"] for d in sorted(matches, key=lambda d: (-d["updated"], d["id"]))[:limit]]


class CatalogueRelease(unittest.TestCase):
    def test_distinct_editions_survive_shared_title(self):
        c = Catalog([doc("a", "shared guide"), doc("b", "shared guide", "two")])
        self.assertEqual(c.search("shared", "one"), ["a"])
        self.assertEqual(c.search("shared", "two"), ["b"])
        self.assertEqual(c.search("shared"), ["a", "b"])

    def test_and_case_and_duplicate_terms(self):
        c = Catalog([doc("a", "ALPHA beta"), doc("b", "alpha gamma")])
        self.assertEqual(c.search("alpha BETA alpha"), ["a"])
        self.assertEqual(c.search("alpha missing"), [])

    def test_order_and_limit(self):
        c = Catalog([doc("b", "topic second", updated=4), doc("a", "topic first", updated=4), doc("z", "topic third", updated=8)])
        self.assertEqual(c.search("topic", limit=2), ["z", "a"])

    def test_empty_and_zero_limit(self):
        c = Catalog([doc("a", "alpha")])
        self.assertEqual(c.search(""), [])
        self.assertEqual(c.search("alpha", limit=0), [])
        self.assertEqual(c.search("alpha", limit=-1), [])

    def test_replacement_removes_old_title(self):
        c = Catalog([doc("a", "old title")])
        c.upsert(doc("a", "new title", updated=3))
        self.assertEqual(c.search("old"), [])
        self.assertEqual(c.search("new"), ["a"])

    def test_replacement_changes_edition_and_rank(self):
        c = Catalog([doc("a", "alpha first"), doc("b", "alpha second", updated=2)])
        c.upsert(doc("a", "alpha first", "two", 7))
        self.assertEqual(c.search("alpha", "one"), ["b"])
        self.assertEqual(c.search("alpha", "two"), ["a"])
        self.assertEqual(c.search("alpha"), ["a", "b"])

    def test_selective_candidate_work(self):
        c = Catalog(doc(str(i), f"common unique{i}") for i in range(3000))
        self.assertEqual(c.search("unique1777"), ["1777"])
        self.assertLessEqual(c.last_examined, 4)

    def test_replaced_memberships_do_not_accumulate_candidates(self):
        c = Catalog([doc("keep", "needle")])
        for i in range(150):
            c.upsert(doc("churn", "needle", updated=i))
            c.upsert(doc("churn", f"other{i}", updated=i+1))
        self.assertEqual(c.search("needle"), ["keep"])
        self.assertLessEqual(c.last_examined, 4)

    def test_replacement_trace_against_current_record_oracle(self):
        rng = random.Random(1977)
        records = {}
        c = Catalog([])
        for step in range(90):
            d = doc(str(rng.randrange(15)), " ".join(rng.sample(["alpha", "beta", "gamma", "delta"], 2)), rng.choice(["one", "two"]), step)
            records[d["id"]] = d
            c.upsert(d)
            for query in ("alpha", "beta gamma", "missing"):
                for edition in (None, "one", "two"):
                    self.assertEqual(c.search(query, edition, 4), oracle(records, query, edition, 4))


class ExportRelease(unittest.TestCase):
    def test_empty_header(self):
        self.assertEqual(to_csv([]), "id,title,edition\n")

    def test_csv_round_trip(self):
        rows = [("a", "Comma, quote\" and\nline", "one"), ("b", "CR\rLF\r\n", "two"), ("c", "", " spaced ")]
        output = to_csv(iter(rows))
        self.assertTrue(output.startswith("id,title,edition\n"))
        self.assertEqual(list(csv.reader(io.StringIO(output, newline=""))), [["id", "title", "edition"]] + [list(r) for r in rows])


if __name__ == "__main__":
    unittest.main()

