class Catalog:
    def __init__(self, documents):
        self._rows = {}
        self._postings = {}
        self._editions = {}
        self.last_examined = 0
        for document in documents:
            self.upsert(document)

    def upsert(self, document):
        current = dict(document)
        id_ = current["id"]
        old = self._rows.get(id_)
        if old is not None:
            for term in set(old["title"].casefold().split()):
                self._remove_membership(self._postings, term, id_)
            self._remove_membership(self._editions, old["edition"], id_)

        self._rows[id_] = current
        for term in set(current["title"].casefold().split()):
            self._postings.setdefault(term, set()).add(id_)
        self._editions.setdefault(current["edition"], set()).add(id_)

    @staticmethod
    def _remove_membership(index, key, id_):
        members = index[key]
        members.remove(id_)
        if not members:
            del index[key]

    def search(self, query, edition=None, limit=20):
        terms = set(query.casefold().split())
        self.last_examined = 0
        if not terms or limit <= 0:
            return []

        postings = []
        for term in terms:
            members = self._postings.get(term)
            if not members:
                return []
            postings.append(members)
        if edition is not None:
            members = self._editions.get(edition)
            if not members:
                return []
            postings.append(members)

        postings.sort(key=len)
        candidates = postings[0].copy()
        for members in postings[1:]:
            candidates.intersection_update(members)
            if not candidates:
                return []

        matches = []
        for id_ in candidates:
            self.last_examined += 1
            document = self._rows[id_]
            if edition is None or document["edition"] == edition:
                matches.append(document)
        return [d["id"] for d in sorted(matches, key=lambda d: (-d["updated"], d["id"]))[:limit]]

